 static ReplayDecision allocateReplay(SQLiteDatabase db,AtomNetSessionR30 state,ResearchWriteQueueR27.Batch b){if(!state.ready()||state.nextPosition!=1||state.trainer.onlineSteps%(10L*64)!=0)return null;Map<String,Object> evidence=summary(db);String proposed=replayPolicy(evidence,state.replayPolicy);if(proposed.equals(state.replayPolicy)||!state.datasetHash.equals(evidence.get("datasetHash")))return null;String run=ResearchContractR30R1.sha(String.valueOf(evidence.get("windowId")));if(run.equals(state.replayEvidenceRun))return null;long from=((Number)evidence.get("fromOrdinal")).longValue(),through=((Number)evidence.get("throughOrdinal")).longValue();ReplayDecision decision=new ReplayDecision(run,state.replayPolicy,proposed,from,through);b.guardBefore(tx->{ResearchInputPinR30R1.requireReady(tx);try(Cursor q=tx.rawQuery("SELECT 1 FROM r30r1_analysis_run r WHERE r.run_id=? AND r.role='ONLINE_RESEARCH' AND r.status='ONLINE_MODEL_ROLE_REGISTERED' AND r.dataset_hash=? AND ("+ResearchInputPinR30R1.validRunSql("r")+")",new String[]{run,state.datasetHash})){return q.moveToFirst()?0:-1;}});state.replayPolicy=proposed;state.replayEvidenceRun=run;state.replayPolicyChanges++;return decision;}
